function countRoutes(m: number, n: number): number {
  const go = (i: number, j: number): number => {
    if (i === 0 || j === 0) return 1; // a straight line along the edge
    return go(i - 1, j) + go(i, j - 1);
  };
  return go(m - 1, n - 1);
}

