function countRoutes(m: number, n: number): number {
  const row = new Array(n).fill(1);
  for (let i = 1; i < m; i++)
    for (let j = 1; j < n; j++)
      row[j] += row[j - 1]; // old row[j] = from above, row[j - 1] = from the left
  return row[n - 1];
}

